INSERT INTO exercises (slug, name, description, instructions, difficulty, equipment, animation_path, thumbnail_path)
VALUES
('battle-ropes', 'Battle Ropes', 'A high-intensity conditioning movement using thick ropes, training the upper back, shoulders, and grip.', 'Anchor the ropes to a fixed point and grab one end in each hand. Step back so the ropes have moderate slack. Drop into a quarter squat with feet shoulder-width. Drive each arm up and down rapidly to send waves through the ropes. Continue for the prescribed work interval.', 'Intermediate', 'Machine', '/assets/animations/battle-ropes.webp', '/assets/thumbnails/battle-ropes-thumb.webp'),
('behind-the-neck-press', 'Behind the Neck Press', 'An overhead press performed with the barbell starting behind the neck, emphasizing the front and side deltoids.', 'Sit or stand with a barbell resting on your upper traps behind your neck. Grip the bar wider than shoulder width. Press the bar straight up overhead until your arms are extended. Lower the bar back to the starting position under control. Repeat for the desired number of reps.', 'Intermediate', 'Barbell', '/assets/animations/behind-the-neck-press.webp', '/assets/thumbnails/behind-the-neck-press-thumb.webp'),
('bench-leg-pull-in', 'Bench Leg Pull-In', 'A supine core exercise on a flat bench, pulling the knees toward the chest to train the rectus abdominis.', 'Lie on your back on a flat bench and grip the sides behind your head for support. Extend your legs straight out with heels just above the bench surface. Pull your knees toward your chest, lifting the hips slightly off the bench. Extend the legs back out under control without letting the heels touch the bench. Repeat for the desired number of repetitions.', 'Beginner', 'Bodyweight', '/assets/animations/bench-leg-pull-in.webp', '/assets/thumbnails/bench-leg-pull-in-thumb.webp'),
('cossack-squat', 'Cossack Squat', 'A wide-stance lateral squat that trains single-leg strength, hip mobility, and adductor flexibility.', 'Stand in a wide stance with toes turned slightly out. Shift your weight to one side, bending that knee and sinking into a deep squat. Keep the trailing leg straight with the heel down and toes up. Drive through the bent leg back to center, then repeat to the other side.', 'Intermediate', 'Bodyweight', '/assets/animations/cossack-squat.webp', '/assets/thumbnails/cossack-squat-thumb.webp'),
('dumbbell-reverse-fly', 'Dumbbell Reverse Fly', 'A hinged isolation exercise raising dumbbells out to the sides, targeting the rear deltoids and upper back.', 'Hinge forward at the hips holding dumbbells with arms hanging down. Keep your back flat and knees slightly bent. Raise the dumbbells out to the sides until level with your shoulders. Lower the dumbbells back with control. Repeat for the desired number of reps.', 'Intermediate', 'Dumbbell', '/assets/animations/dumbbell-reverse-fly.webp', '/assets/thumbnails/dumbbell-reverse-fly-thumb.webp'),
('ez-bar-spider-curl', 'EZ Bar Spider Curl', 'A chest-supported curl over an incline bench with an EZ bar, isolating the biceps with strict form.', 'Lie chest down on an incline bench holding an EZ bar with underhand grip. Let your arms hang straight down from your shoulders. Curl the bar up toward your shoulders. Lower the bar back down with control. Repeat for the desired number of reps.', 'Intermediate', 'Barbell', '/assets/animations/ez-bar-spider-curl.webp', '/assets/thumbnails/ez-bar-spider-curl-thumb.webp'),
('front-squat', 'Front Squat', 'A barbell squat with the bar held in front on the deltoids, emphasizing quads and core.', 'Clean or rack the bar to your front deltoids with elbows high. Squat down keeping torso upright until thighs are parallel. Drive back up. Repeat.', 'Intermediate', 'Barbell', '/assets/animations/front-squat.webp', '/assets/thumbnails/front-squat-thumb.webp'),
('incline-db-curl', 'Incline Dumbbell Curl', 'A bicep curl on an incline bench for a deeper stretch of the long head.', 'Sit on an incline bench set to 45 degrees, holding dumbbells at your sides. Let your arms hang straight down with palms forward. Curl the dumbbells up toward your shoulders. Lower with control to full extension. Repeat.', 'Intermediate', 'Dumbbell', '/assets/animations/incline-db-curl.webp', '/assets/thumbnails/incline-db-curl-thumb.webp'),
('mountain-climbers', 'Mountain Climbers', 'A dynamic bodyweight exercise combining core work with cardio.', 'Start in a high plank position. Drive one knee toward your chest. Quickly switch legs, driving the other knee forward. Continue alternating at a brisk pace. Repeat.', 'Beginner', 'Bodyweight', '/assets/animations/mountain-climbers.webp', '/assets/thumbnails/mountain-climbers-thumb.webp'),
('one-arm-kettlebell-row', 'One Arm Kettlebell Row', 'A unilateral rowing exercise with bench support, building the lats and mid-back one side at a time.', 'Place one hand and knee on a bench for support. Hold a kettlebell in the opposite hand with your arm extended. Pull the kettlebell toward your hip by driving your elbow back. Lower the kettlebell with control. Complete reps on one side, then switch.', 'Intermediate', 'Dumbbell', '/assets/animations/one-arm-kettlebell-row.webp', '/assets/thumbnails/one-arm-kettlebell-row-thumb.webp'),
('plate-loaded-lateral-raise', 'Plate-Loaded Lateral Raise', 'A seated lateral raise on a plate-loaded machine targeting the side deltoids.', 'Set the seat height so that the pivot of the arm pads lines up with the point of your shoulders. Load the plate horns evenly and sit with your back flat against the pad. Push out and up against the pads until your upper arms are roughly level with your shoulders. Lower under control and repeat.', 'Beginner', 'Machine', '/assets/animations/plate-loaded-lateral-raise.webp', '/assets/thumbnails/plate-loaded-lateral-raise-thumb.webp'),
('pull-up', 'Pull-Up', 'A bodyweight compound pull targeting the lats and biceps.', 'Hang from a bar with an overhand grip, slightly wider than shoulder-width. Pull yourself up until your chin is over the bar. Lower yourself under control to a dead hang. Repeat.', 'Intermediate', 'Bodyweight', '/assets/animations/pull-up.webp', '/assets/thumbnails/pull-up-thumb.webp'),
('reverse-grip-lat-pulldown', 'Reverse Grip Lat Pulldown', 'A lat pulldown variation using an underhand grip that increases biceps involvement.', 'Attach a straight bar to a lat pulldown machine. Grip the bar with an underhand grip, shoulder-width apart. Sit and secure your thighs under the pad. Pull the bar down to your upper chest. Return the bar to the starting position with control. Repeat.', 'Intermediate', 'Machine', '/assets/animations/reverse-grip-lat-pulldown.webp', '/assets/thumbnails/reverse-grip-lat-pulldown-thumb.webp'),
('side-lying-lateral-raise', 'Side-Lying Lateral Raise', 'A dumbbell lateral deltoid isolation exercise performed lying on one side on a flat bench.', 'Lie on your side on a flat bench. Hold a dumbbell in your top hand with your arm resting along your side. Keeping your elbow slightly bent, raise the dumbbell upward until your arm is perpendicular to the floor. Lower slowly and repeat.', 'Beginner', 'Dumbbell', '/assets/animations/side-lying-lateral-raise.webp', '/assets/thumbnails/side-lying-lateral-raise-thumb.webp'),
('smith-machine-front-squat', 'Smith Machine Front Squat', 'A squat on the Smith machine with the bar racked across the front of the shoulders.', 'Set the bar at upper-chest height and step under it so it rests across the front of your shoulders. Keep your elbows high and torso upright. Squat until your thighs are at least parallel to the floor. Drive through the middle of your feet to stand and repeat.', 'Beginner', 'Machine', '/assets/animations/smith-machine-front-squat.webp', '/assets/thumbnails/smith-machine-front-squat-thumb.webp'),
('stability-ball-knee-tuck', 'Stability Ball Knee Tuck', 'A plank-position knee tuck with the feet on a stability ball, loading the abs dynamically.', 'Start in a high plank with both shins or the tops of the feet on a stability ball. Brace the core and pull the ball toward the chest by tucking the knees in. Roll it back out to the plank position and repeat.', 'Intermediate', 'Bodyweight', '/assets/animations/stability-ball-knee-tuck.webp', '/assets/thumbnails/stability-ball-knee-tuck-thumb.webp');
